const lockUndeliveredChatTaskSupplements = `-- name: LockUndeliveredChatTaskSupplements :many
SELECT s.task_id, s.message_id, s.chat_session_id, s.workspace_id, s.author_id, s.status, s.created_at FROM chat_task_supplement s
WHERE s.task_id = $1 AND s.status IN ('pending', 'delivering')
ORDER BY s.created_at, s.message_id FOR UPDATE
`

func (q *Queries) LockUndeliveredChatTaskSupplements(ctx context.Context, taskID pgtype.UUID) ([]ChatTaskSupplement, error) {
	rows, err := q.db.Query(ctx, lockUndeliveredChatTaskSupplements, taskID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ChatTaskSupplement{}
	for rows.Next() {
		var i ChatTaskSupplement
		if err := rows.Scan(
			&i.TaskID,
			&i.MessageID,
			&i.ChatSessionID,
			&i.WorkspaceID,
			&i.AuthorID,
			&i.Status,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const requeueChatTaskSupplement = `-- name: RequeueChatTaskSupplement :exec
WITH moved AS (
    UPDATE chat_task_supplement SET status = 'requeued'
    WHERE message_id = $2 AND status IN ('pending', 'delivering')
    RETURNING message_id
)
UPDATE chat_message SET task_id = $1
WHERE id IN (SELECT message_id FROM moved)
`

type RequeueChatTaskSupplementParams struct {
	NextTaskID pgtype.UUID `json:"next_task_id"`
	MessageID  pgtype.UUID `json:"message_id"`
}

func (q *Queries) RequeueChatTaskSupplement(ctx context.Context, arg RequeueChatTaskSupplementParams) error {
	_, err := q.db.Exec(ctx, requeueChatTaskSupplement, arg.NextTaskID, arg.MessageID)
	return err
}

